// TypeScript Version: 4.1

/**
* Status code.
*/
type StatusCode = number;

/**
* Interface describing `dgetrf`.
*/
interface Routine {
	/**
	* Computes an `LU` factorization of a real general matrix `A` using
	* elimination with partial pivoting and row interchanges.
	*
	* The factorization has the form `A = P * L * U`, where `P` is a permutation
	* matrix, `L` is lower trapezoidal with unit diagonal elements, and `U` is
	* upper trapezoidal. The input matrix `A` is overwritten in-place, and the
	* unit diagonal of `L` is not stored. Pivot indices are zero-based.
	*
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input matrix stored in column-major order
	* @param LDA - stride between successive columns of `A`; `LDA >= max(1,M)`
	* @param IPIV - pivot indices
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 1.0, 3.0, 2.0, 4.0 ] );
	* var IPIV = new Int32Array( 2 );
	*
	* dgetrf( 2, 2, A, 2, IPIV );
	* // A => <Float64Array>[ 3, 0.333..., 4, 0.666... ]
	* // IPIV => <Int32Array>[ 1, 1 ]
	*/
	( M: number, N: number, A: Float64Array, LDA: number, IPIV: Int32Array ): StatusCode;

	/**
	* Computes an `LU` factorization using alternative indexing semantics.
	*
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param IPIV - pivot indices
	* @param strideIPIV - stride length for `IPIV`
	* @param offsetIPIV - starting index for `IPIV`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 1.0, 3.0, 2.0, 4.0 ] );
	* var IPIV = new Int32Array( 2 );
	*
	* dgetrf.ndarray( 2, 2, A, 1, 2, 0, IPIV, 1, 0 );
	* // A => <Float64Array>[ 3, 0.333..., 4, 0.666... ]
	* // IPIV => <Int32Array>[ 1, 1 ]
	*/
	ndarray( M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, IPIV: Int32Array, strideIPIV: number, offsetIPIV: number ): StatusCode;
}

/**
* Computes an `LU` factorization of a real general matrix `A` using elimination with partial pivoting and row interchanges.
*
* @param M - number of rows in `A`
* @param N - number of columns in `A`
* @param A - input matrix, stored in column-major order
* @param LDA - stride between successive columns of `A`
* @param IPIV - vector of pivot indices
* @returns status code
*/
declare var dgetrf: Routine;


// EXPORTS //

export = dgetrf;
